		Modifier Bit 0
		false

			nasal

				name = "/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier";
				mod = getprop(name);
				if (mod == nil) {
					setprop(name, 1);
				} elsif (mod == 0 or mod == 2) {
					setprop(name, mod + 1);
				}




				nasal

					name = "/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier";
					mod = getprop(name);
					if (mod == nil) {
						setprop(name, 0);
					} elsif (mod == 1 or mod == 3) {
						setprop(name, mod - 1);
					}






		Modifier Bit 1
		false

			nasal

				name = "/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier";
				mod = getprop(name);
				if (mod == nil) {
					setprop(name, 2);
				} elsif (mod == 0 or mod == 1) {
					setprop(name, mod + 2);
				}




				nasal

					name = "/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier";
					mod = getprop(name);
					if (mod == nil) {
						setprop(name, 0);
					} elsif (mod == 2 or mod == 3) {
						setprop(name, mod - 2);
					}






		View direction; mixture; aileron trim; rudder trim

			true

				nasal


					mod = getprop("/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier");
					if (mod == nil or mod == 0) {
						v = getprop("/sim/current-view/view-number");
						if (v == 0 or v == 4) {
							view.panViewDir(1);
						} else {
							view.panViewDir(-1);
						}
					} elsif (mod == 1) {
						controls.adjMixture(-2);
					} elsif (mod == 2) {
						controls.aileronTrim(-0.75);
					} elsif (mod == 3) {
						controls.rudderTrim(0.75);
					}





			true

				nasal


					mod = getprop("/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier");
					if (mod == nil or mod == 0) {
						v = getprop("/sim/current-view/view-number");
						if (v == 0 or v == 4) {
							view.panViewDir(-1);
						} else {
							view.panViewDir(1);
						}
					} elsif (mod == 1) {
						controls.adjMixture(2);
					} elsif (mod == 2) {
						controls.aileronTrim(0.75);
					} elsif (mod == 3) {
						controls.rudderTrim(-0.75);
					}






		View direction; prop pitch; elevator trim

