					if (mod == nil or mod == 0) {
						view.panViewPitch(1);
					} elsif (mod == 1) {
						controls.adjPropeller(1);
					} elsif (mod == 2) {
						controls.elevatorTrim(0.75);
					} elsif (mod == 3) {
						#
					}





			true

				nasal


					mod = getprop("/input/joysticks/js[0]/thrustmaster-top-gun-afterburner-modifier");
					if (mod == nil or mod == 0) {
						view.panViewPitch(-1);
					} elsif (mod == 1) {
						controls.adjPropeller(-1);
					} elsif (mod == 2) {
						controls.elevatorTrim(-0.75);
					} elsif (mod == 3) {
						#
					}
